<script setup lang="ts">const tones=[['ā á ǎ à','primeiro, segundo, terceiro e quarto tons'],['a','tom neutro: leve e curto']];const speak=(t:string)=>speechSynthesis.speak(new SpeechSynthesisUtterance(t))</script>
<template><section><div class="page-title"><span class="eyebrow">PRONÚNCIA</span><h1>Pinyin e tons</h1><p class="muted">O Pinyin representa sons do mandarim; as marcas indicam o tom.</p></div><div class="grid two-col"><div class="card"><h2>Os quatro tons</h2><div v-for="t in tones" :key="t[0]" class="list-row"><span class="hanzi" style="font-size:24px">{{t[0]}}</span><div class="row-main"><b>{{t[1]}}</b><small>mā · má · mǎ · mà</small></div><button class="pill" @click="speak(t[0])">Ouvir</button></div></div><div class="card"><h2>Treino auditivo</h2><p class="muted">Ouça uma sílaba e identifique o contorno do tom. A aplicação não avalia sua voz sem reconhecimento de fala real.</p><button class="button primary" @click="speak('mā má mǎ mà')">Ouvir contraste</button></div></div></section></template>
